-- Datos ficticios para las pruebas del servicio (módulo M2). Se cargan como superusuario.
SET search_path = nexo, public;

-- Personas: id, número, empresa, área, turno
CREATE TEMP TABLE p (id uuid, grupo uuid, nombre text, tipo text, vence date, numero text, empresa uuid, planta uuid, area uuid, turno uuid);
  SELECT id, grupo, nombre, tipo, CASE WHEN tipo = 'contratista' THEN 'Servicios Demo' END, vence FROM p;
  SELECT grupo, empresa, id, planta, area, turno,
         CASE WHEN grupo = 'a0000000-0000-0000-0000-000000000001' THEN 'f0000000-0000-0000-0000-000000000001'::uuid ELSE 'f0000000-0000-0000-0000-000000000002'::uuid END,
         daterange('2024-01-01', NULL) FROM p;



